 x,w=cols[i*2];z,v=cols[i*2+1];return [p(f'{letters}1 · SAG T2',x,75,w,422),p(f'{letters}2 · AX T2',x,504,w,109),p(f'{letters}3 · SAG T1 после Gd',z,75,v,422),p(f'{letters}4 · AX T1 после Gd',z,504,v,109)]
